/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
root=Path('MIPStarRE')
mods={'.'.join(p.with_suffix('').parts):p for p in root.rglob('*.lean')}
graph={m:[] for m in mods}
for m,p in mods.items():
    for line in p.read_text().splitlines():
        if line.startswith('import '):
            dep=line.split()[1]
            if dep in mods: graph[m].append(dep)
state={}; stack=[]
def visit(m):
    s=state.get(m,0)
    if s==1:
        i=stack.index(m); raise SystemExit('CYCLE: '+' -> '.join(stack[i:]+[m]))
    if s==2:return
    state[m]=1;stack.append(m)
    for d in graph[m]:visit(d)
    stack.pop();state[m]=2
for m in graph:visit(m)
print(f'IMPORT_DAG=acyclic modules={len(graph)} edges={sum(map(len,graph.values()))}')
PY
printf '%s\\n' 'import MIPStarRE.QPBT.Combining.QuantitativeScalars' '#check MIPStarRE.QPBT.pauli_baseline_point_constant_le' '#check MIPStarRE.QPBT.quantitative_native_global_pair_error_le_fractional' > /tmp/qpbt-reach-qs.lean
printf '%s\\n' 'import MIPStarRE.QPBT.Combining.QuantitativeNativeScalars' '#check MIPStarRE.QPBT.quantitative_native_error_rpow_le_separated' '#check MIPStarRE.QPBT.quantitative_native_global_pair_error_bound' > /tmp/qpbt-reach-native.lean
printf '%s\\n' 'import MIPStarRE.QPBT.Test.Soundness.QuantitativeScalars.Bounds' '#check MIPStarRE.QPBT.pauliSoundnessQuantitativePower' '#check MIPStarRE.QPBT.pauli_soundness_quantitative_envelope_nonneg' > /tmp/qpbt-reach-bounds.lean
printf '%s\\n' 'import MIPStarRE.QPBT.Test.Soundness.QuantitativeScalars.Fractional' '#check MIPStarRE.QPBT.pauliSoundnessQuantitativeFractionalDimension' '#check MIPStarRE.QPBT.quantitative_native_global_pair_sqrt_le_fractional_base' '#check MIPStarRE.QPBT.quantitative_native_extraction_sqrt_le_fractional_base' > /tmp/qpbt-reach-fractional.lean
lake env lean /tmp/qpbt-reach-qs.lean >/tmp/qpbt-reach-qs.out
lake env lean /tmp/qpbt-reach-native.lean >/tmp/qpbt-reach-native.out
